export const date = '2026-10-08';
export const guides = [
  {
    file: 'pu-stone-panels-over-painted-masonry.html', image: 'pu-painted-masonry-20261008.svg', product: '/products/pu-stone-panels.html', catalog: '/assets/catalogs/pu-stone-panel-catalog-en.pdf', source: 'https://www.epa.gov/indoor-air-quality-iaq/moisture-control-guidance-building-design-construction-and-maintenance-0', sourceName: 'U.S. EPA moisture-control guidance', related: ['wpc-panels-sunlit-showroom-sample-check.html', 'fca-wall-panel-order-uzbekistan-inland-delivery.html', 'pu-stone-panels-vs-natural-stone.html', 'pvc-wall-panels-humid-areas.html'],
    en: { title: 'PU Stone Panels Over Painted Masonry? | Luvie', description: 'Before specifying PU stone-look panels over painted masonry, check wall moisture, paint adhesion and the exact fixing system with a small site mock-up.', heading: 'Can PU stone-look panels go over a painted masonry wall?', lead: 'A refurbishment buyer may see a sound-looking painted wall and assume a decorative panel can cover it directly. Paint can hide dampness, weak layers or repairs. For a coastal South American renovation, the useful question is whether the whole wall and fixing method are ready—not whether the panel face looks water-resistant.', answer: 'Sometimes, but only after the substrate, paint and moisture source have been assessed and the proposed fixing method has been approved for the exact panel and site.', sections: [
      ['Diagnose the wall before the finish', 'Map peeling paint, efflorescence, stains, cracks and previous water entry. Ask the site team to identify whether the wall is exterior, below grade or beside plumbing. EPA moisture guidance warns against enclosing wet building materials; it is general building guidance, not an approval for any Luvie product. Do not use a new decorative face to hide an unresolved leak.'],
      ['Check what the adhesive or fixing will actually grip', 'A bond to paint is only as reliable as the paint-to-wall bond. Ask the installer and fixing supplier to review the coating, surface preparation, panel weight and current product instructions. If a mechanical system is proposed, locate services and confirm suitable anchors with the project engineer. Do not assume a method used on bare concrete transfers to glossy or flaking paint.'],
      ['Build a representative trial area', 'Select a modest wall area that includes an edge, corner and typical defect. Prepare it as specified, install the actual panel and trim, then inspect attachment and appearance after the agreed observation period. Record who accepted the result and which materials were used. A photograph of a finished wall is not a pull-off test or proof of long-term compatibility.'],
      ['Write the purchase and site handoff', 'Record the panel code, substrate condition, preparation steps, fixing products, edge detail and responsibility for moisture repair. Keep the approved sample and mock-up record with the order. If the wall changes during demolition, stop and revise the detail before installing a full room. Request model-specific instructions and samples from Luvie rather than relying on a generic installation claim.']
    ], closing: 'Send wall photographs, moisture history and the intended panel code so the project team can review a suitable trial detail.' },
    es: { title: '¿Panel PU sobre mampostería pintada? | Luvie', description: 'Antes de especificar paneles de aspecto piedra sobre mampostería pintada, revise humedad, adherencia de la pintura y fijación con una prueba de obra.', heading: '¿Se pueden instalar paneles de aspecto piedra PU sobre una pared pintada?', lead: 'En una reforma, una pared pintada puede parecer firme aunque oculte humedad, capas débiles o reparaciones. En una obra costera sudamericana, importa evaluar el conjunto de pared y fijación, no solo la apariencia de la cara decorativa.', answer: 'En algunos casos, pero solo después de evaluar soporte, pintura y origen de la humedad, y aprobar la fijación para el modelo y la obra concretos.', sections: [
      ['Diagnostique la pared antes del acabado', 'Localice pintura desprendida, salitre, manchas, grietas y entradas de agua previas. Determine si el muro da al exterior, está bajo rasante o junto a tuberías. La guía de la EPA desaconseja encerrar materiales húmedos; es orientación general, no aprobación de un producto Luvie. No tape una fuga sin resolverla.'],
      ['Compruebe a qué se sujetará la fijación', 'La unión adhesiva a la pintura depende también de la unión de la pintura al muro. El instalador y el proveedor de la fijación deben revisar revestimiento, preparación, peso del panel e instrucciones actuales. Si se prevén anclajes, un técnico debe identificar instalaciones ocultas y soportes adecuados. Un método para hormigón desnudo no se traslada automáticamente a pintura brillante o suelta.'],
      ['Haga una prueba representativa', 'Elija un área pequeña con borde, esquina y defecto típico. Prepárela según las instrucciones e instale el panel y la moldura reales. Inspeccione unión y apariencia tras el período de observación acordado. Anote materiales y responsable de aprobación. Una foto del acabado no demuestra adherencia ni compatibilidad a largo plazo.'],
      ['Documente pedido y entrega a obra', 'Registre código del panel, condición del muro, preparación, productos de fijación, remate y responsable de reparar la humedad. Guarde muestra y acta de la prueba. Si el soporte cambia al demoler, revise el detalle antes de cubrir toda la sala. Solicite a Luvie instrucciones y muestras del modelo exacto.']
    ], closing: 'Envíe fotos del muro, antecedentes de humedad y código del panel para estudiar una prueba adecuada.' },
    'pt-br': { title: 'Painel PU sobre alvenaria pintada? | Luvie', description: 'Antes de especificar painéis com aparência de pedra sobre alvenaria pintada, avalie umidade, aderência da tinta e fixação em um teste local.', heading: 'É possível instalar painel PU com aparência de pedra sobre parede pintada?', lead: 'Numa reforma, uma parede pintada pode parecer firme e esconder umidade, camadas fracas ou reparos. Em obras costeiras, a decisão depende da parede completa e da fixação, não apenas da aparência da face decorativa.', answer: 'Em alguns casos, mas apenas após avaliar base, tinta e origem da umidade e aprovar a fixação para o modelo e o local específicos.', sections: [
      ['Diagnostique a parede antes do acabamento', 'Mapeie tinta soltando, eflorescência, manchas, fissuras e entradas de água anteriores. Verifique se a parede é externa, enterrada ou próxima de tubulação. A orientação da EPA alerta contra fechar materiais úmidos; é referência geral, não aprovação de produto Luvie. Não esconda um vazamento com o revestimento.'],
      ['Confira onde a fixação realmente prende', 'Uma colagem sobre tinta também depende da aderência da tinta à parede. Instalador e fornecedor da fixação devem avaliar pintura, preparo, peso do painel e instruções atuais. Com fixação mecânica, o engenheiro deve localizar instalações e definir ancoragens apropriadas. O método para concreto nu não serve automaticamente para tinta lisa ou descascando.'],
      ['Monte uma área-teste representativa', 'Escolha um trecho pequeno com borda, canto e defeito típico. Prepare-o conforme as instruções, aplique painel e arremate reais e avalie fixação e aparência após o período combinado. Registre materiais e aprovação. Uma foto da parede pronta não prova aderência nem compatibilidade duradoura.'],
      ['Registre o pedido e a entrega à obra', 'Anote código, condição da base, preparo, produtos de fixação, arremates e responsável pelo reparo da umidade. Guarde amostra e registro do teste. Se a parede mudar durante a demolição, revise o detalhe antes de cobrir a sala. Peça à Luvie instruções e amostras do modelo exato.']
    ], closing: 'Envie fotos da parede, histórico de umidade e código do painel para avaliar um teste adequado.' },
    ar: { title: 'ألواح PU فوق جدار مطلي: ما الذي يجب فحصه؟ | Luvie', description: 'افحص رطوبة الجدار وتماسك الطلاء وطريقة التثبيت قبل اعتماد ألواح PU الشبيهة بالحجر فوق البناء المطلي.', heading: 'هل يمكن تركيب ألواح PU الشبيهة بالحجر فوق جدار بناء مطلي؟', lead: 'قد يبدو الجدار المطلي سليماً في مشروع تجديد، بينما يخفي رطوبة أو طبقات ضعيفة أو إصلاحات قديمة. القرار الصحيح يتعلق بالجدار وطريقة التثبيت معاً، لا بمظهر وجه اللوح فقط.', answer: 'قد يكون ذلك ممكناً بعد تقييم السطح والطلاء ومصدر الرطوبة واعتماد طريقة التثبيت للطراز والموقع المحددين.', sections: [
      ['افحص الجدار قبل اختيار التشطيب', 'حدد الطلاء المتقشر والترسبات والبقع والشقوق وتسربات الماء السابقة. اسأل هل الجدار خارجي أو تحت مستوى الأرض أو بجوار تمديدات. تحذر إرشادات وكالة حماية البيئة الأمريكية من إغلاق مواد البناء الرطبة؛ وهي إرشادات عامة وليست اعتماداً لمنتج من Luvie. لا تخف تسرباً غير معالج خلف الزينة.'],
      ['تحقق مما سيلتصق به نظام التثبيت', 'يعتمد التصاق المادة بالطلاء على تماسك الطلاء بالجدار. على المركب ومورد مواد التثبيت مراجعة طبقة الطلاء وتجهيز السطح ووزن اللوح والتعليمات الحالية. إذا استُخدمت مثبتات ميكانيكية، فليحدد المهندس الخدمات المخفية والمراسي المناسبة. لا تنقل طريقة الجدار الخرساني المكشوف إلى طلاء لامع أو متقشر تلقائياً.'],
      ['أنشئ مساحة اختبار ممثلة', 'اختر جزءاً صغيراً يشمل حافة وزاوية وعيباً شائعاً. جهزه كما تحدد التعليمات وثبت اللوح والزخرفة الحقيقيين، ثم افحص التثبيت والمظهر بعد مدة المراقبة المتفق عليها. سجل المواد وجهة الاعتماد. صورة جدار مكتمل ليست اختبار التصاق ولا دليلاً على التوافق طويل الأمد.'],
      ['وثق الطلب وتسليم الموقع', 'سجل رمز اللوح وحالة الجدار والتجهيز ومواد التثبيت وتفصيل الحافة والمسؤول عن إصلاح الرطوبة. احتفظ بالعينة وسجل الاختبار. إذا تغير السطح عند إزالة التشطيب القديم، راجع التفصيل قبل تغطية الغرفة كلها. اطلب من Luvie تعليمات وعينات خاصة بالطراز.']
    ], closing: 'أرسل صور الجدار وسجل الرطوبة ورمز اللوح لمراجعة تفصيل اختبار مناسب.' }
  },
  {
    file: 'wpc-panels-sunlit-showroom-sample-check.html', image: 'wpc-sunlit-display-20261008.svg', product: '/products/wpc-wall-panels.html', catalog: '/assets/catalogs/wpc-collection-2026.pdf', source: 'https://www.iso.org/standard/55481.html', sourceName: 'ISO 4892-2 plastics light-exposure method', related: ['pu-stone-panels-over-painted-masonry.html', 'fca-wall-panel-order-uzbekistan-inland-delivery.html', 'south-america-wall-panel-colour-sample-lighting.html', 'can-indoor-wpc-wall-panels-be-used-outside.html'],
    en: { title: 'WPC Panels Behind Shop Windows: Sample Checks | Luvie', description: 'A Gulf showroom buyer guide to sunlight exposure, model-specific evidence and mock-ups for indoor WPC decorative panels placed near glazing.', heading: 'Will an indoor WPC panel keep its look beside a sunlit shop window?', lead: 'A sample approved in a shaded meeting room may be displayed for months beside glazing in a Gulf storefront. That is a different exposure, even though the panel stays indoors. The buyer needs a location-specific sample and evidence request rather than a blanket promise that every WPC finish resists sunlight.', answer: 'Do not infer UV performance from the WPC name. Identify the exact finish, window exposure and acceptable appearance change, then request relevant model-specific test evidence or choose a lower-exposure location.', sections: [
      ['Map the real exposure', 'Note glazing orientation, hours of direct sun, shading, distance to the window and whether merchandise blocks part of the wall. Keep a separate record for each elevation in a multi-store rollout. A panel behind glass is not equivalent to an exterior facade, but filtered daylight can still be relevant to appearance.'],
      ['Ask for test conditions, not a marketing adjective', 'ISO 4892-2 describes laboratory xenon-arc exposure of plastics to daylight or daylight filtered through window glass. It specifies a method, not an automatic pass result for any Luvie panel. If a supplier provides a report, compare product code, finish, specimen, filter, exposure cycle and measured outcome with the proposed application. A report for another colour or coating may not answer the question.'],
      ['Approve a full-scale visual mock-up', 'Place the exact sample and trim at the proposed window, alongside the flooring and lighting. Record photographs and a protected reference sample at installation, then agree who will inspect appearance later. Judge tone, sheen and pattern from normal customer distance as well as near joints. Do not use phone images alone as a quantified colour-change test.'],
      ['Write a decision rule before the order', 'State which locations are shaded, which need further evidence and who accepts any visual variation. If reliable model-specific evidence is unavailable, relocate the panel, add architectural shading or select a finish the project team can verify. Ask for current cleaning instructions separately; cleaning tolerance and light exposure are different questions.']
    ], closing: 'Share the window orientation, sample code and display duration to request relevant current evidence or a trial sample.' },
    es: { title: 'Panel WPC junto a vitrinas soleadas | Luvie', description: 'Guía para revisar exposición solar, informes del modelo y muestras de paneles WPC interiores cerca del vidrio.', heading: '¿Mantendrá su aspecto un panel WPC interior junto a una vitrina soleada?', lead: 'Una muestra aprobada en una sala sombreada puede permanecer meses junto al vidrio de una tienda del Golfo. Sigue en interior, pero la exposición cambia. El comprador necesita una muestra y pruebas para esa ubicación, no una promesa general de resistencia solar de todos los WPC.', answer: 'No deduzca el comportamiento frente a la luz solo del nombre WPC. Defina acabado, exposición y cambio visual aceptable; después solicite pruebas del modelo o elija una zona menos expuesta.', sections: [
      ['Describa la exposición real', 'Anote orientación del vidrio, horas de sol directo, sombras, distancia y objetos que cubren parte del muro. Separe las fachadas en un proyecto de varias tiendas. Detrás de un vidrio no es igual que en exterior, pero la luz filtrada puede afectar la apariencia.'],
      ['Pida condiciones de ensayo, no adjetivos', 'ISO 4892-2 describe la exposición de plásticos a lámparas de xenón para simular luz diurna o filtrada por vidrio. Es un método, no una aprobación automática de paneles Luvie. Compare código, acabado, probeta, filtro, ciclo y resultado del informe con la aplicación prevista. Un ensayo de otro color puede no responder la duda.'],
      ['Apruebe una prueba visual a escala', 'Coloque muestra y moldura exactas junto a la ventana prevista, el suelo y las luces. Guarde fotos y una referencia protegida al instalar; acuerde quién revisará el aspecto más adelante. Examine tono, brillo y dibujo desde la distancia del cliente y cerca de las juntas. Una foto de móvil no cuantifica el cambio de color.'],
      ['Defina la decisión antes del pedido', 'Distinga zonas sombreadas de aquellas que requieren más pruebas y nombre al responsable de aceptar diferencias visuales. Si faltan datos del modelo, cambie la ubicación, añada sombra o elija un acabado verificable. Solicite aparte las instrucciones de limpieza: limpieza y luz son preguntas distintas.']
    ], closing: 'Comparta orientación de la ventana, código de muestra y tiempo de exposición para pedir pruebas actuales.' },
    'pt-br': { title: 'Painel WPC perto de vitrine ensolarada | Luvie', description: 'Confira exposição solar, evidências do modelo e amostras de painéis WPC internos instalados próximos a vidro.', heading: 'Um painel WPC interno manterá a aparência junto a uma vitrine ensolarada?', lead: 'Uma amostra aprovada numa sala à sombra pode ficar meses ao lado do vidro de uma loja no Golfo. Continua em ambiente interno, mas a exposição mudou. O comprador precisa de amostra e evidência para aquele local, não de promessa geral sobre todo acabamento WPC.', answer: 'Não deduza desempenho à luz apenas pelo nome WPC. Defina acabamento, exposição e alteração visual aceitável; peça evidências do modelo ou escolha um local menos exposto.', sections: [
      ['Mapeie a exposição real', 'Registre orientação do vidro, horas de sol direto, sombreamento, distância e mercadorias que cobrem parte da parede. Trate cada fachada separadamente em várias lojas. Atrás do vidro não equivale a uma fachada externa, mas a luz filtrada pode importar para a aparência.'],
      ['Peça condições de ensaio, não adjetivos', 'A ISO 4892-2 descreve exposição laboratorial de plásticos à luz de xenônio, simulando luz natural ou filtrada por vidro. É um método, não aprovação automática de painel Luvie. Compare código, acabamento, corpo de prova, filtro, ciclo e resultado do relatório com o uso planejado. Ensaio de outra cor pode não responder à pergunta.'],
      ['Aprove um trecho visual em escala real', 'Coloque amostra e arremate exatos perto da janela proposta, com piso e iluminação. Guarde fotos e referência protegida na instalação; combine quem inspecionará depois. Avalie tom, brilho e desenho da distância do cliente e junto às emendas. Foto de celular não é medição de alteração de cor.'],
      ['Escreva a regra de decisão antes do pedido', 'Separe locais sombreados dos que exigem mais evidência e nomeie quem aceita variações visuais. Sem dados confiáveis do modelo, mude a posição, inclua sombra ou escolha acabamento verificável. Peça instruções de limpeza à parte: luz e limpeza são questões diferentes.']
    ], closing: 'Envie orientação da vitrine, código da amostra e período de exposição para pedir evidências atuais.' },
    ar: { title: 'ألواح WPC قرب واجهة متجر مشمسة | Luvie', description: 'دليل لفحص تعرض ألواح WPC الداخلية للضوء قرب الزجاج وطلب أدلة خاصة بالطراز وعينة تجريبية.', heading: 'هل يحافظ لوح WPC الداخلي على مظهره قرب واجهة متجر مشمسة؟', lead: 'قد تُعتمد عينة في غرفة مظللة ثم تُعرض أشهراً بجوار زجاج متجر في الخليج. يبقى اللوح داخل المبنى لكن التعرض للضوء يختلف. يحتاج المشتري عينة ودليلاً لهذا الموضع، لا وعداً عاماً بمقاومة كل تشطيبات WPC للشمس.', answer: 'لا تستنتج مقاومة الضوء من اسم WPC. حدد التشطيب والتعرض والتغير البصري المقبول، ثم اطلب تقريراً للطراز المحدد أو اختر موضعاً أقل تعرضاً.', sections: [
      ['ارسم خريطة التعرض الفعلي', 'سجل اتجاه الزجاج وساعات الشمس المباشرة والظل والمسافة والبضائع التي تحجب جزءاً من الجدار. افصل بين واجهات المتاجر في المشروع المتكرر. الموضع خلف الزجاج ليس واجهة خارجية، لكن ضوء النهار المصفى قد يؤثر في المظهر.'],
      ['اطلب شروط الاختبار لا الوصف التسويقي', 'تصف ISO 4892-2 تعريض عينات البلاستيك في المختبر لمصابيح زينون لمحاكاة ضوء النهار أو الضوء المار عبر الزجاج. هي طريقة اختبار وليست نجاحاً تلقائياً لأي لوح من Luvie. قارن رمز المنتج والتشطيب والعينة والمرشح والدورة والنتيجة مع الاستخدام المقصود. تقرير لون آخر قد لا يجيب عن سؤالك.'],
      ['اعتمد نموذجاً بصرياً بالحجم المناسب', 'ضع العينة والحافة الفعليتين قرب النافذة المقصودة ومع الأرضية والإضاءة. احفظ صوراً وعينة مرجعية محمية عند التركيب واتفق على جهة المراجعة لاحقاً. افحص اللون واللمعان والنقش من مسافة الزبون وعند الفواصل. صورة هاتف ليست قياساً رقمياً لتغير اللون.'],
      ['حدد قاعدة القرار قبل الطلب', 'ميز المواضع المظللة عن التي تحتاج أدلة إضافية وحدد من يقبل التفاوت المرئي. إذا غاب دليل موثوق للطراز، غيّر الموضع أو أضف تظليلاً أو اختر تشطيباً يمكن التحقق منه. اطلب تعليمات التنظيف منفصلة؛ تحمل التنظيف والتعرض للضوء مسألتان مختلفتان.']
    ], closing: 'أرسل اتجاه الواجهة ورمز العينة ومدة العرض لطلب دليل حالي مناسب.' }
  },
  {
    file: 'fca-wall-panel-order-uzbekistan-inland-delivery.html', image: 'fca-inland-handoff-20261008.svg', product: '/products/pvc-wall-panels.html', catalog: '/assets/catalogs/dream-house-wall-panel-catalog.pdf', source: 'https://library.iccwbo.org/content/tfb/BOOKS/BK_0049/BK_0049_04_RulesAny.htm', sourceName: 'ICC Incoterms 2020 FCA explanatory notes', related: ['pu-stone-panels-over-painted-masonry.html', 'wpc-panels-sunlit-showroom-sample-check.html', 'fob-vs-cif-wall-panel-orders.html', 'import-wall-panels-china-document-checklist.html'],
    en: { title: 'FCA Wall Panel Orders to Uzbekistan: Buyer Guide | Luvie', description: 'For Uzbekistan importers arranging multimodal freight, define the exact FCA handover point, carrier and documents before ordering wall panels.', heading: 'What should an Uzbekistan wall-panel buyer specify in an FCA order?', lead: 'An Uzbekistan distributor may collect wall panels inland, send them through a port and then move them onward by rail or road. A quote marked only “FCA China” does not identify where the seller hands the cargo to the buyer’s carrier. That missing place can create a dispute before the first container moves.', answer: 'Write “FCA” with a precisely named delivery place, the Incoterms 2020 version, nominated carrier, export-clearance responsibilities and the evidence of handover in the sales contract.', sections: [
      ['Name the place, not just the country', 'The ICC explains that under FCA the named delivery place determines the point at which risk transfers and costs change hands. Seller premises and a separate terminal have different delivery mechanics. Write an address or terminal and confirm who arranges loading or unloading at that point. Check that the commercial invoice, packing list and booking instructions use the same place.'],
      ['Draw the carrier handoff for the route', 'FCA may be used for more than one transport mode, which matters for a shipment involving truck, vessel and inland rail. Identify who nominates the first carrier, who books each leg and who pays each terminal charge. Do not infer these from a short price line. Ask the forwarder to map the actual itinerary and possible handover evidence before the purchase order is signed.'],
      ['Separate trade terms from the product specification', 'Incoterms allocate delivery duties, costs and risk; they do not define panel grade, packing quantity, accepted sample or quality remedy. Attach the exact panel code, dimensions, finish, accessory list and carton labels to the order. If the buyer needs a particular transport or customs document, list it expressly and confirm the party able to provide it. Local import requirements require separate professional checking.'],
      ['Resolve the bill-of-lading question early', 'For some FCA sea shipments a bank may request an on-board bill of lading. The ICC describes an optional mechanism in Incoterms 2020, but it requires appropriate agreement and coordination with the buyer’s carrier. Do not assume the seller controls a carrier appointed by the buyer. Discuss documentary-credit wording with the bank and forwarder before shipment rather than attempting to repair it after dispatch.']
    ], closing: 'Send the proposed pickup location, route and panel list so the quotation can state a clear handover point; obtain local customs advice separately.' },
    es: { title: 'Pedidos FCA de paneles para Uzbekistán | Luvie', description: 'Para importadores que organizan transporte multimodal, defina lugar exacto de entrega FCA, transportista y documentos antes del pedido.', heading: '¿Qué debe precisar un comprador uzbeko en un pedido FCA de paneles?', lead: 'Un distribuidor puede recoger paneles tierra adentro, pasarlos por un puerto y continuar por ferrocarril o carretera hacia Uzbekistán. Una oferta que diga solo «FCA China» no indica dónde se entrega la carga al transportista del comprador. La omisión puede causar disputas antes de mover el contenedor.', answer: 'Incluya FCA con lugar de entrega preciso, versión Incoterms 2020, transportista designado, gestión de exportación y prueba de entrega en el contrato.', sections: [
      ['Indique el lugar, no solo el país', 'La ICC explica que el lugar FCA determina el momento en que cambian riesgo y costos. La entrega en instalaciones del vendedor y en una terminal funciona de modo distinto. Escriba dirección o terminal y acuerde quién carga o descarga allí. Factura, lista de empaque y reserva deben indicar el mismo lugar.'],
      ['Dibuje la entrega al transportista', 'FCA permite varios modos de transporte, útil cuando intervienen camión, barco y ferrocarril. Identifique quién designa al primer transportista, reserva cada tramo y paga cada cargo de terminal. No lo deduzca de una línea de precio. Pida al agente de carga el itinerario y la prueba posible de entrega antes de firmar.'],
      ['Separe el término comercial de la especificación', 'Incoterms distribuye obligaciones, costos y riesgos; no define calidad del panel, unidades por caja, muestra aprobada ni soluciones ante defectos. Adjunte código, dimensiones, acabado, accesorios y marcas de cartón. Si necesita un documento de transporte o aduana, escríbalo expresamente y confirme quién puede emitirlo. Revise aparte las exigencias locales de importación.'],
      ['Resuelva pronto el conocimiento de embarque', 'En ciertos envíos FCA por mar un banco pide conocimiento con anotación a bordo. La ICC describe una opción en Incoterms 2020, que exige acuerdo y coordinación con el transportista del comprador. No suponga que el vendedor controla ese transportista. Revise la carta de crédito con banco y agente antes del despacho.']
    ], closing: 'Comparta punto de recogida, ruta y lista de paneles para redactar una oferta con entrega clara; consulte aparte a un asesor aduanero local.' },
    'pt-br': { title: 'Pedido FCA de painéis para o Uzbequistão | Luvie', description: 'Para importadores com frete multimodal, defina ponto exato de entrega FCA, transportador e documentos antes da compra.', heading: 'O que um comprador do Uzbequistão deve definir num pedido FCA de painéis?', lead: 'Um distribuidor pode retirar painéis no interior, passar por um porto e seguir por trem ou caminhão até o Uzbequistão. Uma proposta escrita apenas “FCA China” não informa onde a carga passa ao transportador do comprador. Essa omissão pode gerar disputa antes de o contêiner sair.', answer: 'Escreva FCA com local de entrega preciso, edição Incoterms 2020, transportador indicado, responsabilidade pelo desembaraço de exportação e comprovante de entrega.', sections: [
      ['Indique o local, não só o país', 'Segundo a ICC, o local FCA define onde o risco passa ao comprador e a divisão de custos. Entrega no estabelecimento do vendedor e em terminal externo têm procedimentos diferentes. Anote endereço ou terminal e combine carga e descarga naquele ponto. Fatura, romaneio e reserva devem repetir o local.'],
      ['Desenhe a passagem ao transportador', 'FCA pode servir a mais de um modal, importante com caminhão, navio e ferrovia. Identifique quem indica o primeiro transportador, reserva cada trecho e paga as taxas de terminal. Não deduza isso de uma linha de preço. Peça ao agente de cargas rota e prova de entrega antes de assinar.'],
      ['Separe condição comercial de especificação', 'Incoterms distribui entrega, custos e riscos; não define classe do painel, unidades por caixa, amostra aceita ou solução de defeitos. Anexe código, medidas, acabamento, acessórios e identificação das caixas. Se houver documento exigido pelo transporte ou alfândega, liste-o e confirme quem pode fornecê-lo. Verifique exigências locais em separado.'],
      ['Resolva cedo o conhecimento de embarque', 'Em algumas operações FCA por mar o banco pede conhecimento com anotação de embarque. A ICC descreve opção nas regras de 2020, mas ela depende de acordo e coordenação com o transportador do comprador. Não presuma que o vendedor controla esse transportador. Alinhe carta de crédito, banco e agente antes do envio.']
    ], closing: 'Envie local de coleta, rota e lista de painéis para uma proposta com entrega clara; obtenha orientação aduaneira local à parte.' },
    ar: { title: 'طلب ألواح بشروط FCA إلى أوزبكستان | Luvie', description: 'حدد نقطة تسليم FCA الدقيقة والناقل والمستندات قبل شراء ألواح الجدران لشحنة متعددة وسائل النقل إلى أوزبكستان.', heading: 'ما الذي يجب تحديده في طلب ألواح بشروط FCA إلى أوزبكستان؟', lead: 'قد يستلم موزع الألواح من موقع داخلي ثم تمر الشحنة بميناء وتواصل بالقطار أو الشاحنة إلى أوزبكستان. عبارة «FCA الصين» وحدها لا تحدد أين تسلم البضاعة إلى ناقل المشتري. قد ينشأ خلاف قبل تحرك الحاوية.', answer: 'اكتب FCA مع مكان تسليم محدد بدقة وإصدار Incoterms 2020 والناقل المعين ومسؤولية التخليص التصديري ودليل التسليم في العقد.', sections: [
      ['اذكر المكان لا الدولة فقط', 'توضح غرفة التجارة الدولية أن مكان التسليم المسمى في FCA يحدد انتقال المخاطر وتوزيع التكاليف. يختلف التسليم في مقر البائع عن التسليم في محطة أخرى. اكتب العنوان أو المحطة واتفق على التحميل أو التفريغ هناك. يجب أن تتوافق الفاتورة وقائمة التعبئة وتعليمات الحجز مع المكان نفسه.'],
      ['ارسم نقطة التسليم للناقل', 'تصلح FCA لأكثر من وسيلة نقل، وهذا مهم عند الجمع بين الشاحنة والسفينة والقطار. حدد من يعين أول ناقل ويحجز كل مرحلة ويدفع رسوم المحطات. لا تستنتج ذلك من سعر مختصر. اطلب من وكيل الشحن رسم المسار ووثيقة إثبات التسليم قبل توقيع الطلب.'],
      ['افصل شرط التجارة عن مواصفة المنتج', 'توزع Incoterms واجبات التسليم والتكلفة والمخاطر؛ ولا تحدد درجة اللوح أو عدد القطع أو العينة المعتمدة أو معالجة العيوب. أرفق رمز اللوح والأبعاد والتشطيب والملحقات وعلامات الصناديق. إذا احتجت وثيقة نقل أو جمرك، اذكرها صراحة وتحقق ممن يستطيع إصدارها. افحص متطلبات الاستيراد المحلية بصورة مستقلة.'],
      ['احسم مسألة سند الشحن مبكراً', 'قد يطلب البنك في بعض شحنات FCA البحرية سند شحن بإشارة التحميل على السفينة. تشرح الغرفة الدولية آلية اختيارية في قواعد 2020 لكنها تتطلب اتفاقاً وتنسيقاً مع ناقل المشتري. لا تفترض أن البائع يتحكم في ناقل عينه المشتري. راجع صياغة الاعتماد مع البنك والوكيل قبل الإرسال.']
    ], closing: 'أرسل مكان الاستلام والمسار وقائمة الألواح لوضع نقطة تسليم واضحة في العرض، واستعن بمختص محلي للجمارك.' }
  }
];
